insert into public.vocabulary_items
(vocabulary_id,term,part_of_speech,core_meaning,senses,word_family,collocations,status)
values
('vocab_efficiently','efficiently','adverb','in a way that works well and does not waste time, energy or money','[{"senseId":"efficiently_1","meaning":"in a way that works well and does not waste time, energy or money","acceptedParaphrases":["without wasting time or energy","in a well-planned way"],"masteryContexts":[{"contextId":"u4_21_efficiently_meaning","text":"The depot manager plans the delivery routes carefully so that the lorries use fuel efficiently.","meaning":"without wasting energy, time or money","wrongMeanings":["at a very high speed whatever the cost","in a cheerful and friendly manner","with a great deal of effort"]},{"contextId":"u4_21_efficiently_paraphrase","text":"Freight trains carry heavy goods more efficiently than lorries because they use less fuel for each tonne.","meaning":"in a way that wastes little energy or money","wrongMeanings":["in a way that costs more to run","in a way that moves much faster","in a way that needs more drivers"]}],"situationDistractors":["The driver forgot the route, took three wrong turns and arrived an hour late.","The warehouse workers searched for twenty minutes before they found the missing boxes.","The ticket office ran out of tickets because nobody had ordered new ones.","The tourists photographed the old bridge from the riverbank.","The cyclist stopped at the traffic lights and waited for the signal to change.","The bus driver announced the next stop and opened the doors."],"gapDistractors":[{"contextId":"u4_21_efficiently_gap_1","answer":"efficiently","wrong":["carelessly","reluctantly","noisily"]},{"contextId":"u4_21_efficiently_gap_2","answer":"efficiently","wrong":["carelessly","noisily","suddenly"]},{"contextId":"u4_21_efficiently_gap_3","answer":"efficiently","wrong":["reluctantly","carelessly","noisily"]}],"spellingErrors":["efficently","effeciently","eficiently","efficiantly","efficeintly","efficienly"],"wordFamilyForms":[{"form":"efficiently","partOfSpeech":"adverb","example":"The new baggage system allows the airport to work more efficiently.","pedagogicallyUseful":true},{"form":"efficient","partOfSpeech":"adjective","example":"Electric trains are efficient because they waste very little energy.","pedagogicallyUseful":true,"altExample":"An efficient driver plans the route before leaving the depot."},{"form":"efficiency","partOfSpeech":"noun","example":"Better planning has improved the efficiency of the city’s bus service.","pedagogicallyUseful":true,"altExample":"The airline introduced a new system to increase efficiency at check-in."}],"masteryPassages":[{"passageId":"u4_21_efficiently_passage_1","contextId":"u4_21_efficiently_gap_1","text":"The new airport terminal was planned with great care. Staff can now process thousands of passengers ____ even during the busiest summer weekends.","answer":"efficiently"},{"passageId":"u4_21_efficiently_passage_2","contextId":"u4_21_efficiently_gap_2","text":"Some companies waste a lot of fuel because their lorries travel half empty. Others plan their routes carefully so that their vehicles are always full and run ____.","answer":"efficiently"}],"contextDependentParaphrases":[],"wrongParaphrases":["without paying any money","without making any noise","without asking for help"],"misleadingDistractors":["very quickly, without careful thought","in a slow and careful way","in a noisy and disorganised way"]}]'::jsonb,'["efficient","efficiency"]'::jsonb,'["work efficiently","run efficiently","use fuel efficiently"]'::jsonb,'live'),
('vocab_demand_4','demand','noun','a strong need or wish for something, especially from customers or the public','[{"senseId":"demand_4_1","meaning":"a strong need or wish for something, especially from customers or the public","acceptedParaphrases":["need","call"],"masteryContexts":[{"contextId":"u4_22_demand_4_meaning","text":"The demand for cheap flights rises sharply every summer.","meaning":"the strong wish of customers to buy something","wrongMeanings":["the number of seats that an airline has","the price that an airline charges","the time that an airline takes to fly"]},{"contextId":"u4_22_demand_4_paraphrase","text":"There is such strong demand for the new tram line that the council plans to build a second one.","meaning":"a strong need from the public for something","wrongMeanings":["a strong complaint from the public about something","a strong rule made by the public about something","a strong threat from the public to stop something"]}],"situationDistractors":["The shop had hundreds of unsold scooters in its warehouse and nobody came to buy them.","The bus company reduced its timetable because very few people used the service.","The factory produced twice as many bicycles as it had planned.","The pilot checked the weather report before the flight.","The tourists queued at the ticket office for the afternoon ferry.","A mechanic changed the oil and checked the tyres."],"gapDistractors":[{"contextId":"u4_22_demand_4_gap_1","answer":"demand","wrong":["fear","permission","respect"]},{"contextId":"u4_22_demand_4_gap_2","answer":"demand","wrong":["costs","wages","prices"]},{"contextId":"u4_22_demand_4_gap_3","answer":"demand","wrong":["safety","comfort","wind"]}],"spellingErrors":["demend","damand","demmand","deamnd","demant","demund"],"masteryPassages":[{"passageId":"u4_22_demand_4_passage_1","contextId":"u4_22_demand_4_gap_1","text":"More and more commuters want to cycle to work. As a result, there is growing ____ for safe cycle lanes in the city centre.","answer":"demand"},{"passageId":"u4_22_demand_4_passage_2","contextId":"u4_22_demand_4_gap_2","text":"The railway company sold out of tickets for Friday evening trains within minutes. Because ____ was so high, the company added three extra services.","answer":"demand"}],"contextDependentParaphrases":[],"wrongParaphrases":["small supply","fixed price","official rule"],"misleadingDistractors":["an order given by a police officer or teacher","the amount of money paid for a service","the supply of goods that a company has available"],"teacherNote":"Unit 4 item (demand_4): the noun sense. Unit 1 vocab_demand is the verb \"to require a lot of effort\"; separate item that shares only the lexical spelling list."}]'::jsonb,'[]'::jsonb,'["high demand","growing demand","meet demand"]'::jsonb,'live'),
('vocab_invention','invention','noun','something newly created or designed that did not exist before','[{"senseId":"invention_1","meaning":"something newly created or designed that did not exist before","acceptedParaphrases":["creation","new device"],"masteryContexts":[{"contextId":"u4_23_invention_meaning","text":"Her latest invention is a folding electric scooter that fits inside a school bag.","meaning":"a newly designed device","wrongMeanings":["an old tool that people no longer use","a popular story about travel","a natural feature of the landscape"]},{"contextId":"u4_23_invention_paraphrase","text":"The bicycle was a remarkable invention, because it gave ordinary people a cheap way to travel.","meaning":"something that was created and did not exist before","wrongMeanings":["the repair of something that was broken","the discovery of something that was hidden","the sale of something that was cheap"]}],"situationDistractors":["The explorers found a hidden valley that nobody had ever mapped before.","The mechanic repaired the old engine and the bus ran again.","The museum displayed old posters from the nineteenth century.","The ferry left the harbour at noon and reached the island before dark.","A cyclist waited patiently at the traffic lights.","The guide gave everyone a map of the old harbour."],"gapDistractors":[{"contextId":"u4_23_invention_gap_1","answer":"invention","wrong":["repair","price","weight"]},{"contextId":"u4_23_invention_gap_2","answer":"invention","wrong":["repair","sale","cost"]},{"contextId":"u4_23_invention_gap_3","answer":"invention","wrong":["mistake","complaint","holiday"]}],"spellingErrors":["invension","inventian","invenshun","invantion","inventon","invetion"],"wordFamilyForms":[{"form":"invention","partOfSpeech":"noun","example":"The invention of the compass helped sailors find their way across the open sea.","pedagogicallyUseful":true},{"form":"invent","partOfSpeech":"verb","example":"Who was the first person to invent the bicycle?","pedagogicallyUseful":true},{"form":"inventor","partOfSpeech":"noun","example":"The inventor of the telephone, Alexander Graham Bell, was born in Scotland.","pedagogicallyUseful":true},{"form":"inventive","partOfSpeech":"adjective","example":"The students came up with an inventive way to reduce traffic outside the school.","pedagogicallyUseful":true}],"masteryPassages":[{"passageId":"u4_23_invention_passage_1","contextId":"u4_23_invention_gap_1","text":"People have travelled by boat for thousands of years. The ____ of the steam engine in the eighteenth century, however, changed ships and trains for ever.","answer":"invention"},{"passageId":"u4_23_invention_passage_2","contextId":"u4_23_invention_gap_2","text":"Karl Benz built one of the first petrol-powered cars in 1885. His ____ was so successful that other engineers soon began to copy it.","answer":"invention"}],"contextDependentParaphrases":[],"wrongParaphrases":["discovery","repair","collection"],"misleadingDistractors":["the discovery of something that already existed in nature","a small repair made to an old machine","a story about life in the future"]}]'::jsonb,'["invent","inventor","inventive"]'::jsonb,'["great invention","useful invention","the invention of"]'::jsonb,'live'),
('vocab_machinery','machinery','noun','large powered devices, considered together, that are used to do work in industry, farming or construction','[{"senseId":"machinery_1","meaning":"large powered devices, considered together, that are used to do work in industry, farming or construction","acceptedParaphrases":["mechanical devices","heavy powered devices"],"masteryContexts":[{"contextId":"u4_24_machinery_meaning","text":"Farmers now use heavy machinery to plant and harvest crops across large fields.","meaning":"large powered devices used to do work","wrongMeanings":["workers who are hired to help with a job","buildings where goods are stored and sold","animals that are trained to pull heavy loads"]},{"contextId":"u4_24_machinery_paraphrase","text":"The port has invested in new machinery for unloading containers from ships.","meaning":"powered devices used for lifting and moving heavy loads","wrongMeanings":["storage areas used for keeping goods dry","offices used for managing the shipping staff","contracts used for sending goods overseas"]}],"situationDistractors":["Farmers planted every seed by hand, working in the fields from dawn until dark.","The warehouse was full of wooden boxes, stacked from floor to ceiling.","The workers carried the bricks up the ladder one by one.","The ferry left the harbour at noon with two hundred people on board.","The tourists photographed the old castle from the harbour wall.","A cyclist stopped beside the road to fix a puncture."],"gapDistractors":[{"contextId":"u4_24_machinery_gap_1","answer":"machinery","wrong":["furniture","clothing","luggage"]},{"contextId":"u4_24_machinery_gap_2","answer":"machinery","wrong":["furniture","scenery","clothing"]},{"contextId":"u4_24_machinery_gap_3","answer":"machinery","wrong":["furniture","clothing","uniforms"]}],"spellingErrors":["machinary","mashinery","machinry","machienery","machnery","machinerry"],"masteryPassages":[{"passageId":"u4_24_machinery_passage_1","contextId":"u4_24_machinery_gap_1","text":"The building site was noisy from early morning. Cranes, diggers and other heavy ____ moved tons of earth every hour.","answer":"machinery"},{"passageId":"u4_24_machinery_passage_2","contextId":"u4_24_machinery_gap_2","text":"Modern ports are very busy. Without powerful ____ to lift the containers, ships would wait for days to be unloaded.","answer":"machinery"}],"contextDependentParaphrases":[],"wrongParaphrases":["office furniture","building materials","safety clothing"],"misleadingDistractors":["a group of workers who operate vehicles","the buildings where factories are located","the money spent on running a factory"]}]'::jsonb,'[]'::jsonb,'["heavy machinery","farm machinery","operate machinery"]'::jsonb,'live'),
('vocab_advertisement_4','advertisement','noun','a notice, picture, film or message designed to persuade people to buy or use something','[{"senseId":"advertisement_4_1","meaning":"a notice, picture, film or message designed to persuade people to buy or use something","acceptedParaphrases":["promotional message","paid promotion"],"masteryContexts":[{"contextId":"u4_25_advertisement_4_meaning","text":"The bus company paid for a huge advertisement on the side of every double-decker bus.","meaning":"a notice designed to persuade people to use a service","wrongMeanings":["a notice designed to warn people of danger","a notice designed to give people directions","a notice designed to tell people the time"]},{"contextId":"u4_25_advertisement_4_paraphrase","text":"The advertisement promised free Wi-Fi on all trains, but passengers found that the signal was weak.","meaning":"a message designed to persuade people to buy or use something","wrongMeanings":["a message designed to warn people of delays","a message designed to thank people for waiting","a message designed to teach people a skill"]}],"situationDistractors":["A police officer stopped the traffic so that a group of children could cross the road.","The station announcer reminded everyone to keep their luggage with them.","The newspaper published a long report about the new motorway.","The taxi driver carried the suitcases to the hotel entrance.","The tourists queued at the ticket office to buy tickets for the afternoon ferry.","The mechanic changed a wheel while the family waited beside the road."],"gapDistractors":[{"contextId":"u4_25_advertisement_4_gap_1","answer":"advertisement","wrong":["timetable","ticket","warning"]},{"contextId":"u4_25_advertisement_4_gap_2","answer":"advertisement","wrong":["timetable","suitcase","engine"]},{"contextId":"u4_25_advertisement_4_gap_3","answer":"advertisement","wrong":["ticket","suitcase","engine"]}],"spellingErrors":["advertisment","advertizement","adverticement","advertisemant","adversisement","advertismant"],"wordFamilyForms":[{"form":"advertisement","partOfSpeech":"noun","example":"The advertisement on the side of the bus promised free travel for children.","pedagogicallyUseful":true},{"form":"advertise","partOfSpeech":"verb","example":"Airlines advertise their cheapest tickets on social media.","pedagogicallyUseful":true,"altExample":"The railway company decided to advertise its new night service on local radio."},{"form":"advertising","partOfSpeech":"noun","example":"Most of the company’s income comes from advertising on buses and trams.","pedagogicallyUseful":true,"altExample":"Television advertising is expensive, so small companies often use posters instead."}],"masteryPassages":[{"passageId":"u4_25_advertisement_4_passage_1","contextId":"u4_25_advertisement_4_gap_1","text":"Posters line the walls of the underground station. One bright ____ shows a smiling family and invites travellers to book cheap holidays by train.","answer":"advertisement"},{"passageId":"u4_25_advertisement_4_passage_2","contextId":"u4_25_advertisement_4_gap_2","text":"The airline spent millions on a new television ____. In thirty seconds, it tried to convince viewers that flying with them was cheaper and friendlier than any rival.","answer":"advertisement"}],"contextDependentParaphrases":[],"wrongParaphrases":["safety warning","travel timetable","news report"],"misleadingDistractors":["a warning notice put up for passengers","a timetable showing when trains arrive","a report written by a journalist"],"teacherNote":"Unit 4 item (advertisement_4), separate from Unit 3 advertisement; shares only the lexical spelling list."}]'::jsonb,'["advertise","advertising"]'::jsonb,'["television advertisement","online advertisement","place an advertisement"]'::jsonb,'live'),
('vocab_enormous','enormous','adjective','extremely large','[{"senseId":"enormous_1","meaning":"extremely large","acceptedParaphrases":["huge","gigantic"],"masteryContexts":[{"contextId":"u4_26_enormous_meaning","text":"An enormous crane lifted the bridge sections into place one by one.","meaning":"extremely large in size","wrongMeanings":["extremely strong for its weight","extremely slow to operate","extremely new in design"]},{"contextId":"u4_26_enormous_paraphrase","text":"The tunnel project cost an enormous amount of money, but it saved hours of travelling time every day.","meaning":"very great in amount","wrongMeanings":["surprisingly low and fair","paid slowly over many years","shared equally between cities"]}],"situationDistractors":["The tiny car could hardly carry two people and one small bag.","The path beside the river was so narrow that only one cyclist could pass at a time.","The model train was no bigger than a pencil case.","The ferry arrived at the port and the passengers walked off slowly.","The pilot spoke to the control tower and checked the weather report.","The cyclist stopped at the traffic lights and waited for the signal to change."],"gapDistractors":[{"contextId":"u4_26_enormous_gap_1","answer":"enormous","wrong":["silent","popular","expensive"]},{"contextId":"u4_26_enormous_gap_2","answer":"enormous","wrong":["ancient","empty","awful"]},{"contextId":"u4_26_enormous_gap_3","answer":"enormous","wrong":["crowded","closed","narrow"]}],"spellingErrors":["enormus","enourmous","enormuos","anormous","enormouse","enomous"],"masteryPassages":[{"passageId":"u4_26_enormous_passage_1","contextId":"u4_26_enormous_gap_1","text":"The new container ship is longer than four football pitches. Its ____ size means that only a few ports in the world can receive it.","answer":"enormous"},{"passageId":"u4_26_enormous_passage_2","contextId":"u4_26_enormous_gap_2","text":"The storm left an ____ hole in the middle of the motorway. Drivers had to turn back, and repairs took several weeks.","answer":"enormous"}],"contextDependentParaphrases":[],"wrongParaphrases":["tiny","fragile","sudden"],"misleadingDistractors":["extremely important to many people","extremely expensive to build","extremely old and badly damaged"]}]'::jsonb,'[]'::jsonb,'["enormous size","enormous amount","absolutely enormous"]'::jsonb,'live'),
('vocab_equipment_4','equipment','noun','the tools, devices and items needed for a particular purpose','[{"senseId":"equipment_4_1","meaning":"the tools, devices and items needed for a particular purpose","acceptedParaphrases":["gear","necessary tools"],"masteryContexts":[{"contextId":"u4_27_equipment_4_meaning","text":"The airline checks all emergency equipment, including life jackets and oxygen masks, before every flight.","meaning":"the items needed for a particular purpose","wrongMeanings":["the staff needed for a particular job","the rules needed for a particular purpose","the money needed for a particular task"]},{"contextId":"u4_27_equipment_4_paraphrase","text":"Railway workers need special equipment to repair the tracks at night.","meaning":"the tools and devices needed to do a job","wrongMeanings":["the permission needed to start a job","the training needed to pass a test","the time needed to finish a project"]}],"situationDistractors":["The passengers waited in the departure hall until their gate was announced.","The coach driver told the group to be back at the bus by six o’clock.","The workers took a break and drank tea beside the road.","The tourists photographed the old harbour from the hill above the town.","A mechanic repaired the brakes while the family waited beside the road.","The air steward served drinks and then collected the empty cups."],"gapDistractors":[{"contextId":"u4_27_equipment_4_gap_1","answer":"equipment","wrong":["furniture","tickets","luggage"]},{"contextId":"u4_27_equipment_4_gap_2","answer":"equipment","wrong":["furniture","clothing","luggage"]},{"contextId":"u4_27_equipment_4_gap_3","answer":"equipment","wrong":["posters","tickets","luggage"]}],"spellingErrors":["equipement","equipmant","ekwipment","equiptment","equipmet","equipmment"],"wordFamilyForms":[{"form":"equipment","partOfSpeech":"noun","example":"Engineers use special equipment to test the strength of each bridge.","pedagogicallyUseful":true},{"form":"equip","partOfSpeech":"verb","example":"Airlines must equip every aircraft with life jackets and oxygen masks.","pedagogicallyUseful":true,"altExample":"The council plans to equip all its buses with cameras for safety."},{"form":"equipped","partOfSpeech":"adjective","example":"The new coaches are fully equipped with air conditioning and charging points.","pedagogicallyUseful":true,"altExample":"Rescue boats must be properly equipped before they leave the harbour."}],"masteryPassages":[{"passageId":"u4_27_equipment_4_passage_1","contextId":"u4_27_equipment_4_gap_1","text":"Every aircraft carries life jackets, oxygen masks and a first-aid kit. Engineers inspect all this ____ regularly to make sure it works.","answer":"equipment"},{"passageId":"u4_27_equipment_4_passage_2","contextId":"u4_27_equipment_4_gap_2","text":"The mountain rescue team arrived with ropes, stretchers and radios. Without the right ____, they could not have reached the injured climbers.","answer":"equipment"}],"contextDependentParaphrases":[],"wrongParaphrases":["staff","tickets","rules"],"misleadingDistractors":["the people who work in a team","the rules that must be followed during a job","the money spent on a project"],"teacherNote":"Unit 4 item (equipment_4), separate from Unit 2 equipment; shares only the lexical spelling list."}]'::jsonb,'["equip","equipped"]'::jsonb,'["safety equipment","emergency equipment","rescue equipment"]'::jsonb,'live'),
('vocab_collision','collision','noun','an accident in which moving vehicles or objects hit each other','[{"senseId":"collision_1","meaning":"an accident in which moving vehicles or objects hit each other","acceptedParaphrases":["crash","accident between vehicles"],"masteryContexts":[{"contextId":"u4_28_collision_meaning","text":"A fog warning was issued after a collision involving more than twenty cars.","meaning":"a crash between moving vehicles","wrongMeanings":["a race between two moving vehicles","a signal between moving vehicles","a gap between moving vehicles"]},{"contextId":"u4_28_collision_paraphrase","text":"The pilot turned sharply to avoid a mid-air collision with another aircraft.","meaning":"an accident in which things hit each other","wrongMeanings":["a meeting in which things come together peacefully","a decision to change the direction of travel","a delay caused by bad weather"]}],"situationDistractors":["The two trains passed each other safely on parallel tracks.","A lorry broke down on the hard shoulder, and the driver called for help.","The cyclist braked gently and stopped at the red light.","The tourists took photographs of the old harbour from the pier.","The ticket machine at the station accepted only coins.","The guide handed out maps and explained the timetable for the day."],"gapDistractors":[{"contextId":"u4_28_collision_gap_1","answer":"collision","wrong":["race","meeting","journey"]},{"contextId":"u4_28_collision_gap_2","answer":"collision","wrong":["meeting","race","party"]},{"contextId":"u4_28_collision_gap_3","answer":"collision","wrong":["race","meeting","delay"]}],"spellingErrors":["colision","collission","collizion","colission","collsion","collisoin"],"masteryPassages":[{"passageId":"u4_28_collision_passage_1","contextId":"u4_28_collision_gap_1","text":"Dense fog covered the motorway on Monday morning. Visibility was so poor that a ____ between three cars delayed traffic for two hours.","answer":"collision"},{"passageId":"u4_28_collision_passage_2","contextId":"u4_28_collision_gap_2","text":"Air traffic controllers monitor every aircraft on a radar screen. Their main duty is to keep planes at safe distances from one another so that a ____ never happens.","answer":"collision"}],"contextDependentParaphrases":[],"wrongParaphrases":["delay","breakdown","detour"],"misleadingDistractors":["a sudden stop caused by a red light","a disagreement between two drivers about the route","a fault in the brakes of a vehicle"]}]'::jsonb,'[]'::jsonb,'["head-on collision","mid-air collision","avoid a collision"]'::jsonb,'live'),
('vocab_organisation','organisation','noun','a group of people who work together for a particular purpose, such as a company, charity or public body','[{"senseId":"organisation_1","meaning":"a group of people who work together for a particular purpose, such as a company, charity or public body","acceptedParaphrases":["association","official body"],"masteryContexts":[{"contextId":"u4_29_organisation_meaning","text":"The road safety organisation visits schools to teach children how to cross busy streets.","meaning":"a group of people working together for a particular purpose","wrongMeanings":["a building where people learn together","a plan for arranging a project carefully","a class of children who study together"]},{"contextId":"u4_29_organisation_paraphrase","text":"Air travel is regulated by an international organisation that sets safety standards for all airlines.","meaning":"an official body set up to do a particular job","wrongMeanings":["an official event held to celebrate a success","an official law made to control a business","an official report written to describe a problem"]}],"situationDistractors":["A group of friends met by chance on the platform and chatted until the train arrived.","One man built a small boat alone in his garden over several years.","The shop on the station concourse sells newspapers and snacks.","The mechanic checked the oil and filled the tank with petrol.","The ferry captain welcomed everyone on board and pointed out the lifeboats.","The cyclist put on a helmet and fixed a light to the front of the bike."],"gapDistractors":[{"contextId":"u4_29_organisation_gap_1","answer":"organisation","wrong":["bridge","timetable","engine"]},{"contextId":"u4_29_organisation_gap_2","answer":"organisation","wrong":["driver","ticket","station"]},{"contextId":"u4_29_organisation_gap_3","answer":"organisation","wrong":["engineer","aeroplane","island"]}],"spellingErrors":["organisasion","orginisation","organistion","oraganisation","organisaton","organization"],"wordFamilyForms":[{"form":"organisation","partOfSpeech":"noun","example":"Every large organisation needs clear rules about safety.","pedagogicallyUseful":true},{"form":"organise","partOfSpeech":"verb","example":"Students can organise a road safety campaign with the help of their teachers.","pedagogicallyUseful":true,"altExample":"Volunteers will organise a cycle ride through the city next Saturday."},{"form":"organised","partOfSpeech":"adjective","example":"The airport is very well organised, so passengers never get lost.","pedagogicallyUseful":true,"altExample":"An organised team of ground staff can clean a plane in twenty minutes."}],"masteryPassages":[{"passageId":"u4_29_organisation_passage_1","contextId":"u4_29_organisation_gap_1","text":"Every year, a road safety ____ visits hundreds of schools. Its volunteers teach children how to cross busy streets safely.","answer":"organisation"},{"passageId":"u4_29_organisation_passage_2","contextId":"u4_29_organisation_gap_2","text":"Airlines must follow strict rules. These rules are set by an international ____ whose members come from almost every country.","answer":"organisation"}],"contextDependentParaphrases":[],"wrongParaphrases":["arrangement","competition","celebration"],"misleadingDistractors":["the way in which things are arranged","a plan made for a long journey","a building where people work"]}]'::jsonb,'["organise","organised"]'::jsonb,'["international organisation","charity organisation","public organisation"]'::jsonb,'live'),
('vocab_participant_4','participant','noun','a person who takes part in an activity, event or trial','[{"senseId":"participant_4_1","meaning":"a person who takes part in an activity, event or trial","acceptedParaphrases":["person involved","member of the group"],"masteryContexts":[{"contextId":"u4_30_participant_4_meaning","text":"Each participant in the road safety workshop learned how to give first aid.","meaning":"a person who takes part in an event","wrongMeanings":["a person who watches an event from the side","a person who plans an event beforehand","a person who pays for an event to be held"]},{"contextId":"u4_30_participant_4_paraphrase","text":"Every participant in the trial received a free bicycle helmet.","meaning":"a person involved in a test or study","wrongMeanings":["a person who judges a test or study","a person who writes about a test or study","a person who sells equipment for a study"]}],"situationDistractors":["The spectators clapped from the pavement as the cyclists rode past.","The organiser stood at the finish line with a stopwatch and a microphone.","A sponsor gave the cycling club some money but did not attend the event.","The taxi driver took a shortcut through the old town.","The tourists bought postcards at the kiosk near the harbour.","A cyclist waited at the traffic lights for the green signal."],"gapDistractors":[{"contextId":"u4_30_participant_4_gap_1","answer":"participant","wrong":["spectator","engineer","pilot"]},{"contextId":"u4_30_participant_4_gap_2","answer":"participant","wrong":["passenger","spectator","inspector"]},{"contextId":"u4_30_participant_4_gap_3","answer":"participant","wrong":["spectator","engineer","journalist"]}],"spellingErrors":["participent","particpant","partisipant","participaunt","particapant","particiant"],"wordFamilyForms":[{"form":"participant","partOfSpeech":"noun","example":"Each participant in the trial recorded how they travelled to school.","pedagogicallyUseful":true},{"form":"participate","partOfSpeech":"verb","example":"Students from five schools will participate in the road safety week.","pedagogicallyUseful":true,"altExample":"Anyone over sixteen can participate in the city cycling event."},{"form":"participation","partOfSpeech":"noun","example":"Parents’ participation in the car-free day was higher than expected.","pedagogicallyUseful":true,"altExample":"Active participation in the trial helped the scientists collect useful data."}],"masteryPassages":[{"passageId":"u4_30_participant_4_passage_1","contextId":"u4_30_participant_4_gap_1","text":"The city held a car-free day to encourage cleaner travel. Every ____ agreed to leave their car at home and go to work by bus, tram or bicycle.","answer":"participant"},{"passageId":"u4_30_participant_4_passage_2","contextId":"u4_30_participant_4_gap_2","text":"Researchers tested a new road safety app with fifty drivers. Each ____ used the app for a month and then answered questions about their driving.","answer":"participant"}],"contextDependentParaphrases":[],"wrongParaphrases":["person watching","person organising","person paying"],"misleadingDistractors":["a person who watches an event from the crowd","a person who plans and manages an event","a person who travels on a bus or train"],"teacherNote":"Unit 4 item (participant_4), separate from Unit 3 participant; shares only the lexical spelling list."}]'::jsonb,'["participate","participation"]'::jsonb,'["trial participant","active participant","every participant"]'::jsonb,'live')
